//
// ?iterateCellsAlongLine@Pathfinder@@QAEHABUICoord2D@@0W4PathfindLayerEnum@@PAURva003E3650Struct@@@Z
// retail 0x003E3650, 538 bytes.  This is the cell-space overload reached by
// Pathfinder's world-space forwarder at 0x003E7F20 (ILT 0x0004940E).
//
// Retail's per-cell predicate is a concrete BFME object/template query: a
// type-4 cell supplies an obstacle ObjectID, GameLogic resolves it, and the
// final ThingTemplate in its override chain is tested at +0xd0.  The payload
// is the two-word record consumed by this overload; its first word receives
// the matching object and its second word is the ignored ObjectID.

typedef int Int;
typedef int ObjectID;

extern "C" int __cdecl abs( Int n );
#pragma intrinsic(abs)

struct ICoord2D
{
	Int x;
	Int y;
};

struct IRegion2D
{
	ICoord2D lo;
	ICoord2D hi;
};

enum PathfindLayerEnum
{
	LAYER_INVALID = 0,
	LAYER_GROUND = 1
};

// upstream Overridable layout: vptr at +0, next override at +4.  The body
// calls the existing retail ILT for this real method; it is deliberately
// declared, not reimplemented here.
class Overridable
{
public:
	const Overridable *getFinalOverride() const;

	void *m_vtable;
	Overridable *m_nextOverride;
};

// BFME ThingTemplate's kind-of word is at +0xd0 in the retail layout.
class ThingTemplate : public Overridable
{
public:
	unsigned char m_unmodelled_008[0xc8];
	unsigned int m_kindOf;
};

class Object
{
public:
	Int m_unknown00;
	ThingTemplate *m_template;
	unsigned char m_unmodelled_008[0x74 - 0x08];
	ObjectID m_id;
};

class GameLogic
{
public:
	Object *findObjectByID( ObjectID id );
};

// This is the existing single BFME game-logic global at 0x012f0898.  No TU
// local definition is introduced: all users resolve the same storage.
extern GameLogic *TheBfmeGameLogic;

class PathfindCellInfo
{
public:
	unsigned char m_unmodelled_000[0x20];
	ObjectID m_obstacleID;
};

class PathfindCell
{
public:
	PathfindCellInfo *m_info;
	Int m_unmodelled_004;
	Int m_unmodelled_008;
	unsigned int m_packed;

	Int getRawType( void ) const { return m_packed & 0x7; }
	ObjectID getObstacleID( void ) const;
};

inline ObjectID PathfindCell::getObstacleID( void ) const
{
	PathfindCellInfo *info = m_info;
	if (info != 0)
		return info->m_obstacleID;
	return 0;
}

class PathfindLayer
{
public:
	PathfindCell *getCell( Int x, Int y );

private:
	unsigned char m_unmodelled_000[0x44];
};

struct Rva003E3650Struct
{
	Object *m_found;
	ObjectID m_ignoreID;
};

class Pathfinder
{
public:
	Int iterateCellsAlongLine( const ICoord2D &start, const ICoord2D &end,
		PathfindLayerEnum layer, Rva003E3650Struct *info );
	PathfindCell *getCell( PathfindLayerEnum layer, Int x, Int y );

private:
	unsigned char m_unmodelled_000[0x10];
	PathfindCell **m_map;
	IRegion2D m_extent;
	unsigned char m_unmodelled_024[0x85c - 0x24];
	PathfindLayer m_layers[16];
};

inline PathfindCell *Pathfinder::getCell( PathfindLayerEnum layer,
	Int x, Int y )
{
	if (x >= m_extent.lo.x && x <= m_extent.hi.x &&
		y >= m_extent.lo.y && y <= m_extent.hi.y)
	{
		if (layer > 1 && layer <= 15)
		{
			PathfindCell *cell = m_layers[layer].getCell( x, y );
			if (cell)
				return cell;
		}
		return &m_map[x][y];
	}
	return 0;
}

Int Pathfinder::iterateCellsAlongLine( const ICoord2D &start,
	const ICoord2D &end, PathfindLayerEnum layer,
	Rva003E3650Struct *info )
{
	Int delta_x = abs( end.x - start.x );
	Int delta_y = abs( end.y - start.y );

	Int xinc2, yinc1, xinc1, numpixels, numadd, den;
	Int yinc2, num;

	if (delta_x >= delta_y)
	{
		numpixels = delta_x + 1;
		num = 2 * delta_y - delta_x;
		numadd = delta_y << 1;
		den = 2 * (delta_y - delta_x);
		xinc2 = 1;
		yinc2 = 0;
		yinc1 = 1;
		xinc1 = 1;
	}
	else
	{
		numpixels = delta_y + 1;
		num = 2 * delta_x - delta_y;
		numadd = delta_x << 1;
		den = 2 * (delta_x - delta_y);
		yinc2 = 1;
		xinc2 = 0;
		yinc1 = 1;
		xinc1 = 1;
	}

	if (start.x > end.x)
	{
		xinc2 = -xinc2;
		xinc1 = -1;
	}
	if (start.y > end.y)
	{
		yinc2 = -yinc2;
		yinc1 = -1;
	}

	Int x = start.x;
	Int y = start.y;

	for (Int curpixel = 0; curpixel < numpixels; curpixel++)
	{
		PathfindCell *cell = getCell( layer, x, y );
		if (cell == 0)
			return 0;

		if (cell->getRawType() == 4)
		{
			Object *object = TheBfmeGameLogic->findObjectByID(
				cell->getObstacleID());
			if (object)
			{
				ThingTemplate *objectTemplate = object->m_template;
				if (objectTemplate && objectTemplate->m_nextOverride)
				{
					const ThingTemplate *finalTemplate =
						static_cast<const ThingTemplate *>(
							objectTemplate->m_nextOverride->getFinalOverride());
					if (finalTemplate->m_kindOf & 2)
					{
						if (object->m_id != info->m_ignoreID)
						{
							info->m_found = object;
							return 1;
						}
					}
				}
			}
		}

		if (num < 0)
		{
			num += numadd;
			x += xinc2;
			y += yinc2;
		}
		else
		{
			y += yinc1;
			num += den;
			x += xinc1;
		}
	}

	return 0;
}
